// ─── File: src/main/java/com/bank/perf/service/BenchmarkService.java ───
package com.bank.perf.service;

import com.bank.perf.dto.BenchmarkResult;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.*;

@Service
@Slf4j
public class BenchmarkService {

    // ═══ BENCHMARK 1: Primitive sum ═══
    public BenchmarkResult benchmarkPrimitiveSum(int size) {
        int[] data = new int[size];
        Random rnd = new Random(42);
        for (int i = 0; i < size; i++) data[i] = rnd.nextInt(10000);

        // Warmup
        for (int w = 0; w < 5; w++) { sumLoop(data); sumStream(data); sumParallel(data); }

        long loopTime = timeNs(() -> sumLoop(data));
        long streamTime = timeNs(() -> sumStream(data));
        long parallelTime = timeNs(() -> sumParallel(data));

        String winner = loopTime <= streamTime && loopTime <= parallelTime ? "FOR_LOOP"
            : parallelTime <= streamTime ? "PARALLEL_STREAM" : "STREAM";

        return new BenchmarkResult("Primitive sum (int[])", size,
            Map.of("for_loop_ns", loopTime, "stream_ns", streamTime, "parallel_ns", parallelTime),
            winner, size < 1000 ? "Small data: loop wins (no overhead)"
                : size > 100000 ? "Large data: parallel wins (multiple cores)"
                : "Medium data: loop ≈ stream (JIT optimizes both)");
    }

    private long sumLoop(int[] data) {
        long sum = 0;
        for (int d : data) sum += d;
        return sum;
    }

    private long sumStream(int[] data) {
        return IntStream.of(data).asLongStream().sum();
    }

    private long sumParallel(int[] data) {
        return IntStream.of(data).parallel().asLongStream().sum();
    }

    // ═══ BENCHMARK 2: Filter + Map + Reduce (BigDecimal) ═══
    public BenchmarkResult benchmarkFilterMapReduce(int size) {
        List<BigDecimal> amounts = new ArrayList<>(size);
        Random rnd = new Random(42);
        for (int i = 0; i < size; i++) amounts.add(BigDecimal.valueOf(rnd.nextInt(1000000)));

        BigDecimal threshold = BigDecimal.valueOf(500000);

        // Warmup
        for (int w = 0; w < 3; w++) {
            filterMapReduceLoop(amounts, threshold);
            filterMapReduceStream(amounts, threshold);
        }

        long loopTime = timeNs(() -> filterMapReduceLoop(amounts, threshold));
        long streamTime = timeNs(() -> filterMapReduceStream(amounts, threshold));
        long parallelTime = timeNs(() -> filterMapReduceParallel(amounts, threshold));

        return new BenchmarkResult("Filter+Map+Reduce (BigDecimal)", size,
            Map.of("for_loop_ns", loopTime, "stream_ns", streamTime, "parallel_ns", parallelTime),
            loopTime <= streamTime ? "FOR_LOOP" : "STREAM",
            "Multi-step pipeline: stream ≈ loop due to fusion. " +
            "Parallel helps at large sizes.");
    }

    private BigDecimal filterMapReduceLoop(List<BigDecimal> amounts, BigDecimal threshold) {
        BigDecimal sum = BigDecimal.ZERO;
        for (BigDecimal amt : amounts) {
            if (amt.compareTo(threshold) > 0) {
                sum = sum.add(amt.multiply(new BigDecimal("1.18")));  // add GST
            }
        }
        return sum;
    }

    private BigDecimal filterMapReduceStream(List<BigDecimal> amounts, BigDecimal threshold) {
        return amounts.stream()
            .filter(amt -> amt.compareTo(threshold) > 0)
            .map(amt -> amt.multiply(new BigDecimal("1.18")))
            .reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    private BigDecimal filterMapReduceParallel(List<BigDecimal> amounts, BigDecimal threshold) {
        return amounts.parallelStream()
            .filter(amt -> amt.compareTo(threshold) > 0)
            .map(amt -> amt.multiply(new BigDecimal("1.18")))
            .reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    private long timeNs(Runnable task) {
        long start = System.nanoTime();
        task.run();
        return System.nanoTime() - start;
    }
}
```

