package com.bank.perf.controller;

import com.bank.perf.dto.BenchmarkResult;
import com.bank.perf.service.BenchmarkService;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;
import java.util.List;

@RestController
@RequestMapping("/api/v1/benchmark")
@RequiredArgsConstructor
public class BenchmarkController {

    private final BenchmarkService benchmarkService;

    @GetMapping("/primitive-sum")
    public BenchmarkResult primitiveSum(@RequestParam(defaultValue = "100000") int size) {
        return benchmarkService.benchmarkPrimitiveSum(size);
    }

    @GetMapping("/filter-map-reduce")
    public BenchmarkResult filterMapReduce(@RequestParam(defaultValue = "100000") int size) {
        return benchmarkService.benchmarkFilterMapReduce(size);
    }

    @GetMapping("/all")
    public List<BenchmarkResult> all() {
        return List.of(
            benchmarkService.benchmarkPrimitiveSum(100),
            benchmarkService.benchmarkPrimitiveSum(100000),
            benchmarkService.benchmarkFilterMapReduce(100),
            benchmarkService.benchmarkFilterMapReduce(100000)
        );
    }
}
