package com.bank.perf.service;

import org.junit.jupiter.api.Test;
import java.util.stream.IntStream;
import static org.assertj.core.api.Assertions.*;

class PerformanceTest {

    @Test
    void streamAndLoopProduceSameResult() {
        int[] data = IntStream.rangeClosed(1, 1000).toArray();

        long loopSum = 0;
        for (int d : data) loopSum += d;

        long streamSum = IntStream.of(data).asLongStream().sum();
        long parallelSum = IntStream.of(data).parallel().asLongStream().sum();

        assertThat(streamSum).isEqualTo(loopSum);     // identical results
        assertThat(parallelSum).isEqualTo(loopSum);   // identical results
    }

    @Test
    void intStreamAvoidAutoboxing() {
        // IntStream: no boxing — int stays int
        int sum1 = IntStream.rangeClosed(1, 100).sum();  // pure primitives

        // Stream<Integer>: BOXING — int → Integer for each element
        int sum2 = IntStream.rangeClosed(1, 100).boxed()
            .reduce(0, Integer::sum);  // Integer objects created!

        assertThat(sum1).isEqualTo(sum2);  // same result, different performance
    }

    @Test
    void useIntStreamForPrimitives() {
        // GOOD: IntStream for primitive operations
        long sum = IntStream.rangeClosed(1, 1_000_000).sum();
        assertThat(sum).isEqualTo(500000500000L);

        // BAD: Stream<Integer> creates 1 million Integer objects!
        // IntStream.rangeClosed(1, 1_000_000).boxed().reduce(0, Integer::sum);
    }
}
